def sgui(cfg):
    valid=target_valid()
    L=[HEADER.rstrip(),f'cmp_pop2_target_valid = {{ scope = country is_shown = {{ {valid} }} }}']
    for kind,arr,var in [('amount',cfg['amounts'],'cmp_pop2_amount_index'),('literacy',cfg['literacy'],'cmp_pop2_literacy_index'),('qualification',cfg['qualifications'],'cmp_pop2_qualification_index'),('profession',cfg['professions'],'cmp_pop2_profession_index'),('wealth',cfg['wealth'],'cmp_pop2_wealth_index')]:
        for i,x in enumerate(arr,1):
            L += [f"cmp_pop2_{kind}_{x['id']}_selected = {{ scope = country is_shown = {{ var:{var} = {i} }} }}",f"cmp_pop2_select_{kind}_{x['id']} = {{ scope = country is_valid = {{ always = yes }} effect = {{ cmp_pop2_select_{kind}_{x['id']}_effect = yes }} }}"]
    L += ['cmp_pop2_society_confirmed = { scope = country is_shown = { has_variable = cmp_pop2_society_confirmed } }','cmp_pop2_toggle_society_confirmation = { scope = country is_valid = { always = yes } effect = { cmp_pop2_toggle_society_confirmation_effect = yes } }']
    req={
      'add_population':'has_variable = cmp_pop2_amount_index','remove_population':'has_variable = cmp_pop2_amount_index','set_literacy':'has_variable = cmp_pop2_literacy_index','spawn_profession':'has_variable = cmp_pop2_amount_index has_variable = cmp_pop2_profession_index','set_qualification':'has_variable = cmp_pop2_profession_index has_variable = cmp_pop2_qualification_index','set_wealth':'has_variable = cmp_pop2_wealth_index','neutralize':'always = yes','clear_society_modifiers':'always = yes','preset_industrial':'always = yes','preset_educated':'always = yes','preset_stable':'always = yes'}
    for id_,extra in req.items(): L.append(f"cmp_pop2_{id_} = {{ scope = country is_valid = {{ {valid} {extra} }} effect = {{ cmp_pop2_{id_}_effect = yes }} }}")
    L += [f"cmp_pop2_assimilate = {{ scope = country is_valid = {{ {valid} has_variable = cmp_pop2_society_confirmed }} effect = {{ cmp_pop2_assimilate_effect = yes }} }}",f"cmp_pop2_convert_religion = {{ scope = country is_valid = {{ {valid} has_variable = cmp_pop2_society_confirmed }} effect = {{ cmp_pop2_convert_religion_effect = yes }} }}"]
    for x in cfg['social_steps']:
        for k in ['loyalists','radicals','reduce_radicals']: L.append(f"cmp_pop2_{k}_{x['id']} = {{ scope = country is_valid = {{ {valid} }} effect = {{ cmp_pop2_{k}_{x['id']}_effect = yes }} }}")
    for x in cfg['migration']: L.append(f"cmp_pop2_migration_{x['id']} = {{ scope = country is_valid = {{ {valid} }} effect = {{ cmp_pop2_migration_{x['id']}_effect = yes }} }}")
    for x in cfg['workforce']: L.append(f"cmp_pop2_workforce_{x['id']} = {{ scope = country is_valid = {{ {valid} }} effect = {{ cmp_pop2_workforce_{x['id']}_effect = yes }} }}")
    for code,name in [(1,'added'),(2,'removed'),(3,'literacy'),(4,'profession'),(5,'qualification'),(6,'wealth'),(7,'neutralized'),(8,'assimilated'),(9,'religion'),(10,'society_clear'),(11,'industrial'),(12,'educated'),(13,'stable'),(14,'loyalists'),(15,'radicals'),(16,'radicals_down'),(17,'migration'),(18,'workforce'),(-1,'no_target'),(-2,'wrong_target')]:
        L.append(f"cmp_pop2_feedback_{name} = {{ scope = country is_shown = {{ var:cmp_pop2_feedback = {code} }} }}")
    return '\n'.join(L)+'\n'

