def accessibilize_population_block(block:str)->str:
    """Beta15.1 readability pass for the state Population 2.0 page."""
    import re
    font_map={11:13,12:13,13:14,14:15,15:17,16:18,20:22}
    def fs(m):
        n=int(m.group(1)); return f"fontsize = {font_map.get(n,n)}"
    block=re.sub(r'fontsize\s*=\s*(\d+)',fs,block)
    block=re.sub(r'fontsize_min\s*=\s*10', 'fontsize_min = 11', block)
    # Slightly larger header/target/legacy controls while retaining existing layout.
    block=block.replace('size = { 180 38 }','size = { 180 42 }').replace('size = { 170 34 }','size = { 170 38 }')
    block=block.replace('size = { 188 38 }','size = { 188 42 }').replace('size = { 178 34 }','size = { 178 38 }')
    return block

